    /*******************************************************************************************************
    * The code from this section is executed once the form is loaded.                                      *
    *                                                                                                      *
    * Depending on the stage of the form lifecycle when a particular action should be performed,           *
    * you can use on the following hooks:                                                                  *
    *                                                                                                      *
    * fd.rendered()     the code is executed once the form is rendered                                     *
    *                                                                                                      *
    * fd.beforeSave()   the code is executed right before saving the form. If returns Promise, the saving  *
    *                   does not proceed until the Promise is resoved. If the Promise is rejected,         * 
    *                   the saving interrupts. This is the appropriate place for adding custom validation. *
    *                                                                                                      *
    * fd.saved()        the code is executed once the form is submitted                                    *
    *                                                                                                      *
    * The following predefined variables can be utilized in the code:                                      *
    *                                                                                                      *
    * fd    an instance of the current form                                                                *
    * $     jQuery object                                                                                  *
    *                                                                                                      *
    *******************************************************************************************************/
 fd.rendered(function () {
     //Populate email with test data
     fd.field('Email').value ='marcus.vance@example.com';
     
    // Hide and disable fields on initial load
    fd.control('Message').hidden = true;
    fd.field('ClientSource').hidden = true;
    ['Discount', 'OrderTotal', 'ClientSource', 'PaymentProcessingFee'].forEach(f => fd.field(f).disabled = true);

    // Initialize discount rate
    window.discount = 0;

    // Define function triggered by the 'Look Me Up' button
    window.GetClientData = function () {
        const emailInput = (fd.field('Email').value || '').trim().toLowerCase();
        if (!emailInput) {
            alert('Please enter an email address first.');
            return;
        }

        const widget = fd.field('ClientSource').widget;
        if (!widget || !widget.dataSource) {
            console.warn('ClientSource widget data is not yet available.');
            return;
        }

        const client = widget.dataSource.data().find(item => 
            (item.value || '').toString().trim().toLowerCase() === emailInput
        );

        if (client) {
            const props = client.props;
            fd.field('Name').value = props['Name'];
            fd.field('Phone').value = props['Phone number'];
            fd.field('Emai').value = props['Email'];
            fd.field('Address_1').value = props['Address line 1'];
            fd.field('Address_2').value = props['Address line 2'];
            fd.field('State').value = props['State'];
            fd.field('Country').value = props['Country'];
            fd.field('ZIP').value = props['ZIP'];
            fd.field('CouponCode').value = props['Personal coupon code'];

            const discountText = (props['Discount'] || '0').replace('%', '').trim();
            window.discount = parseFloat(discountText) || 0;

            fd.control('Message').text = `<div class="alert alert-success">You have a ${discountText}% discount</div>`;
        } else {
            fd.control('Message').text = `<div class="alert alert-warning">No records found. Contact our sales team for support.</div>`;
        }
        fd.control('Message').hidden = false;
    };

    // Configure OrderDetails DataTable
    const dt = fd.control('OrderDetails');
    
    ['UnitPrice', 'Amount'].forEach(fieldName => {
        const col = dt.columns.find(c => c.field === fieldName);
        if (col) col.editable = () => false;
    });

    dt.$on('change', rows => {
        if (rows) {
            rows.forEach(row => {
                const unitPrice = Number(row.__Product?.props?.['Unit Price']) || 0;
                row.set('UnitPrice', unitPrice);
            });
        }
    });

    // Calculate Discounts
    window.Discount = function () {
        const coupon = (fd.field('CouponCode').value || '').trim();
        const widget = fd.field('ClientSource').widget;

        if (widget && widget.dataSource) {
            const match = widget.dataSource.data().find(item => item.props['Personal coupon code'] === coupon);
            if (match) {
                window.discount = parseFloat(match.props['Discount'].replace('%', '').trim()) || 0;
            }
        }

        const subtotal = dt.aggregates.Amount.sum || 0;
        const itemsTotal = dt.aggregates.Quantity.sum || 0;
        const additionalDiscountPercent = itemsTotal > 10 ? 10 : itemsTotal >= 4 ? 5 : 0;

        fd.field('Discount').value = subtotal * ((window.discount + additionalDiscountPercent) / 100);
    };

    // Recalculate totals on payment method change
    fd.field('PaymentMethod').$on('change', value => {
        if (!value) {
            fd.field('OrderTotal').clear();
            fd.field('PaymentProcessingFee').value = 0;
            return;
        }

        const subtotal = dt.aggregates.Amount.sum || 0;
        const discountVal = fd.field('Discount').value || 0;
        const netTotal = subtotal - discountVal;

        const fee = value === 'Credit card' ? netTotal * 0.05 : 0;
        fd.field('PaymentProcessingFee').value = fee;
        fd.field('OrderTotal').value = netTotal + fee;
    });
});
